@import "tailwindcss";

@layer base {
  :root {
    --font-serif: "Cormorant Garamond", Georgia, serif;
    --font-sans: "Plus Jakarta Sans", system-ui, sans-serif;
  }

  body {
    font-family: var(--font-sans);
    background-color: #0c0d0e;
    color: #f4f2ee;
  }

  h1, h2, h3, .font-editorial {
    font-family: var(--font-serif);
  }
}

/* Custom scrollbars for dashboard and chat */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.03);
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(197, 160, 89, 0.4);
}

import React from 'react';
import { AppProvider, useApp } from './context/AppContext';
import { PersonaBar } from './components/PersonaBar';
import { Navbar } from './components/Navbar';
import { ProductCatalog } from './components/ProductCatalog';
import { PartnerWebpage } from './components/PartnerWebpage';
import { PartnerDashboard } from './components/PartnerDashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { OrdersView } from './components/OrdersView';
import { LiveChatWidget } from './components/LiveChatWidget';
import { CheckoutModal } from './components/CheckoutModal';
import { SecurityMatrixModal } from './components/SecurityMatrixModal';
import { Footer } from './components/Footer';

const AppContent: React.FC = () => {
  const { currentView, currentUser, selectedPartnerId } = useApp();

  return (
    <div className="min-h-screen bg-[#0c0d0e] flex flex-col font-sans selection:bg-[#c5a059] selection:text-black">
      {/* Multi-role Persona Switching & RBAC indicator bar */}
      <PersonaBar />

      {/* Main Top Bar navigation adhering to Top Bar Contract */}
      <Navbar />

      {/* Main Dynamic View */}
      <main className="flex-1">
        {currentView === 'catalog' && <ProductCatalog />}
        {currentView === 'partner' && <PartnerWebpage />}
        {currentView === 'dashboard' && (
          currentUser.role === 'admin' && !selectedPartnerId ? (
            <AdminDashboard />
          ) : (
            <PartnerDashboard />
          )
        )}
        {currentView === 'orders' && <OrdersView />}
      </main>

      {/* Persistent Footer */}
      <Footer />

      {/* Modals and Floating Interactive Widgets */}
      <LiveChatWidget />
      <CheckoutModal />
      <SecurityMatrixModal />
    </div>
  );
};

export default function App() {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
}

import {createRoot} from 'react-dom/client';
import App from './App.tsx';
import './index.css';

createRoot(document.getElementById('root')!).render(<App />);

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { MessageSquare, X, Send, Lock, ShieldCheck, Sparkles, User } from 'lucide-react';

export const LiveChatWidget: React.FC = () => {
  const {
    activeChatThreadId,
    closeChat,
    chatThreads,
    currentUser,
    sendChatMessage,
    partners
  } = useApp();

  const [messageText, setMessageText] = useState('');

  if (!activeChatThreadId) return null;

  const currentThread = chatThreads.find(t => t.id === activeChatThreadId);
  if (!currentThread) return null;

  const partner = partners.find(p => p.id === currentThread.partnerId);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!messageText.trim()) return;

    sendChatMessage(currentThread.id, messageText);
    setMessageText('');
  };

  return (
    <div className="fixed bottom-5 right-5 z-50 w-full max-w-sm sm:max-w-md bg-neutral-950 border border-white/20 rounded shadow-2xl flex flex-col h-[500px] overflow-hidden text-xs">
      {/* Header */}
      <div className="p-3.5 bg-neutral-900 border-b border-white/10 flex items-center justify-between">
        <div className="flex items-center gap-2.5">
          <div className="relative">
            <div className="w-8 h-8 rounded-full bg-[#c5a059]/20 text-[#c5a059] flex items-center justify-center font-bold font-editorial text-sm border border-[#c5a059]/30">
              {partner?.name.charAt(0) || 'A'}
            </div>
            <span className="absolute bottom-0 right-0 w-2 h-2 rounded-full bg-emerald-500 border border-neutral-900" />
          </div>

          <div>
            <div className="flex items-center gap-1.5">
              <span className="font-semibold text-white">{currentThread.partnerName}</span>
              <span className="text-[10px] text-neutral-400 font-mono">({partner?.location.split(',')[0]})</span>
            </div>
            <span className="text-[10px] text-neutral-400 block font-light">
              Director: {partner?.leadDesigner}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {currentThread.hasPurchase && (
            <span className="text-[10px] font-mono text-emerald-400 bg-emerald-500/10 border border-emerald-500/30 px-2 py-0.5 rounded flex items-center gap-1">
              <Lock className="w-2.5 h-2.5" />
              <span>Sealed</span>
            </span>
          )}

          <button
            onClick={closeChat}
            className="p-1 rounded text-neutral-400 hover:text-white hover:bg-white/10"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Product Context Banner (if inquiring about a specific product) */}
      {currentThread.productTitle && (
        <div className="px-3.5 py-2 bg-white/[0.03] border-b border-white/5 flex items-center justify-between text-[11px]">
          <div className="flex items-center gap-2 truncate">
            {currentThread.productImage && (
              <img
                src={currentThread.productImage}
                alt=""
                className="w-5 h-5 rounded object-cover border border-white/10 shrink-0"
              />
            )}
            <span className="text-neutral-300 font-editorial truncate">
              Piece: <strong className="text-white">{currentThread.productTitle}</strong>
            </span>
          </div>
          {currentThread.orderId && (
            <span className="text-[10px] font-mono text-[#c5a059] shrink-0">
              #{currentThread.orderId}
            </span>
          )}
        </div>
      )}

      {/* Privacy Isolation Alert Banner */}
      {currentThread.hasPurchase ? (
        <div className="px-3 py-1.5 bg-emerald-950/30 border-b border-emerald-500/20 text-[10px] text-emerald-300 flex items-center gap-1.5">
          <ShieldCheck className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
          <span>
            <strong>Confidential Order Channel:</strong> Quarantined from all competing partners. Only you, {currentThread.partnerName}, and Platform Admins can see this thread.
          </span>
        </div>
      ) : (
        <div className="px-3 py-1 bg-white/[0.02] border-b border-white/5 text-[10px] text-neutral-400 flex items-center gap-1">
          <Lock className="w-3 h-3 text-[#c5a059] shrink-0" />
          <span>Direct confidential atelier communication</span>
        </div>
      )}

      {/* Message Stream */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {currentThread.messages.map(msg => (
          <div
            key={msg.id}
            className={`flex flex-col ${
              msg.isSystemNotice
                ? 'items-center my-2'
                : msg.senderId === currentUser.id
                ? 'items-end'
                : 'items-start'
            }`}
          >
            {msg.isSystemNotice ? (
              <div className="p-2 bg-amber-500/10 border border-amber-500/30 text-amber-200 text-[11px] rounded text-center max-w-[90%] leading-relaxed font-light">
                {msg.content}
              </div>
            ) : (
              <div
                className={`max-w-[85%] rounded px-3 py-2 text-xs leading-relaxed ${
                  msg.senderId === currentUser.id
                    ? 'bg-[#c5a059] text-black font-medium'
                    : 'bg-white/10 text-neutral-200 border border-white/10'
                }`}
              >
                <div className="flex items-center justify-between gap-3 text-[9px] opacity-75 mb-0.5 font-mono">
                  <span>{msg.senderName.split(' ')[0]}</span>
                  <span>{msg.timestamp}</span>
                </div>
                <p>{msg.content}</p>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Input */}
      <form onSubmit={handleSend} className="p-2.5 bg-neutral-900 border-t border-white/10 flex items-center gap-2">
        <input
          type="text"
          value={messageText}
          onChange={e => setMessageText(e.target.value)}
          placeholder={`Message ${currentThread.partnerName}...`}
          className="flex-1 bg-white/5 border border-white/10 rounded px-3 py-2 text-xs text-white placeholder-neutral-500 focus:outline-none focus:border-[#c5a059]"
        />
        <button
          type="submit"
          disabled={!messageText.trim()}
          className="p-2 bg-[#c5a059] hover:bg-[#d4b069] disabled:opacity-40 text-black font-semibold rounded transition-colors"
        >
          <Send className="w-3.5 h-3.5" />
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Product, Partner } from '../types';
import { HERO_IMAGE } from '../data/mockData';
import { Sparkles, MessageSquare, ArrowRight, ShieldCheck, SlidersHorizontal, Search, CheckCircle } from 'lucide-react';

export const ProductCatalog: React.FC = () => {
  const { products, partners, navigateTo, openChatForPartner, setCheckoutProduct, setIsCheckoutModalOpen } = useApp();

  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [selectedPartnerFilter, setSelectedPartnerFilter] = useState<string>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');

  const categories = ['All', 'Eveningwear', 'Tailoring', 'Outerwear', 'Artisanal Silk', 'Resort'];

  const filteredProducts = products.filter(product => {
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    const matchesPartner = selectedPartnerFilter === 'All' || product.partnerId === selectedPartnerFilter;
    const matchesSearch =
      product.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      product.partnerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      product.materials.some(m => m.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesPartner && matchesSearch;
  });

  return (
    <div className="min-h-screen bg-[#0c0d0e] text-[#f4f2ee]">
      {/* Editorial Hero Campaign */}
      <section className="relative border-b border-white/10 overflow-hidden">
        <div className="max-w-7xl mx-auto px-6 py-14 lg:py-20 grid grid-cols-1 lg:grid-cols-12 gap-10 items-center">
          <div className="lg:col-span-6 space-y-6">
            <div className="inline-flex items-center gap-2 text-xs uppercase tracking-[0.25em] text-[#c5a059] font-medium">
              <span className="w-6 h-[1px] bg-[#c5a059]" />
              <span>Independent Haute Houses & Bespoke Portals</span>
            </div>

            <h1 className="text-4xl sm:text-5xl lg:text-6xl font-editorial font-light tracking-tight leading-[1.08] text-white text-balance">
              Where independent ateliers open their private boutiques.
            </h1>

            <p className="text-base text-neutral-300 leading-relaxed max-w-xl font-light">
              Explore the master catalog of all collective garments. Select any design to enter that partner’s dedicated digital webpage, inspect handcrafting records, and converse directly with their master artisans with strict transactional privacy.
            </p>

            <div className="pt-2 flex flex-wrap items-center gap-4 text-xs text-neutral-400">
              <div className="flex items-center gap-1.5">
                <CheckCircle className="w-4 h-4 text-[#c5a059]" />
                <span>Dedicated Partner Boutiques</span>
              </div>
              <span className="text-white/20">·</span>
              <div className="flex items-center gap-1.5">
                <CheckCircle className="w-4 h-4 text-[#c5a059]" />
                <span>Direct Live Atelier Concierge</span>
              </div>
              <span className="text-white/20">·</span>
              <div className="flex items-center gap-1.5">
                <ShieldCheck className="w-4 h-4 text-[#c5a059]" />
                <span>Purchase Isolation Guarantee</span>
              </div>
            </div>
          </div>

          <div className="lg:col-span-6 relative">
            <div className="relative aspect-[16/10] overflow-hidden rounded-sm border border-white/15 shadow-2xl bg-neutral-900 group">
              <img
                src={HERO_IMAGE}
                alt="Haute couture collective editorial"
                referrerPolicy="no-referrer"
                className="w-full h-full object-cover object-center group-hover:scale-102 transition-transform duration-700"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/25 to-transparent pointer-events-none" />

              <div className="absolute bottom-4 left-5 right-5 flex items-end justify-between">
                <div>
                  <span className="text-[10px] uppercase tracking-widest text-[#c5a059]">Autumn / Winter Bespoke Guild</span>
                  <p className="text-sm font-editorial text-white">4 Distinct European & Asian Couture Houses</p>
                </div>
                <span className="text-xs text-white/70 font-mono tracking-wider">PARIS · MILAN · KYOTO · MARSEILLE</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Featured Partner Houses Selector Strip */}
      <section className="border-b border-white/10 bg-[#121417]/60 py-8 px-6">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xs uppercase tracking-[0.2em] text-[#a1a1aa] font-semibold">
              Partner Houses in the Guild (Click to visit webpage directly)
            </h2>
            <span className="text-xs text-[#c5a059]">Independent brand pages & isolated vaults</span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {partners.map(partner => (
              <button
                key={partner.id}
                onClick={() => navigateTo('partner', partner.id)}
                className="text-left p-4 rounded bg-white/[0.03] hover:bg-white/[0.07] border border-white/10 hover:border-[#c5a059]/40 transition-all group flex flex-col justify-between h-36"
              >
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs uppercase tracking-wider text-[#a1a1aa] group-hover:text-[#c5a059] transition-colors">
                      {partner.location}
                    </span>
                    <span className="text-[10px] font-mono text-white/40">Est. {partner.founded}</span>
                  </div>
                  <h3 className="font-editorial text-lg text-white font-medium group-hover:translate-x-0.5 transition-transform">
                    {partner.name}
                  </h3>
                  <p className="text-xs text-neutral-400 line-clamp-2 mt-1 leading-relaxed">
                    {partner.specialty}
                  </p>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-white/5 text-[11px] text-[#c5a059]">
                  <span>Visit Boutique Page</span>
                  <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1 transition-transform" />
                </div>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Catalog Filtering & Controls */}
      <section className="max-w-7xl mx-auto px-6 pt-10 pb-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-white/10 pb-6">
          {/* Category Tabs (Clean button controls) */}
          <div className="flex items-center gap-1 overflow-x-auto pb-2 md:pb-0 scrollbar-none">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3.5 py-1.5 text-xs font-medium rounded transition-all whitespace-nowrap ${
                  selectedCategory === cat
                    ? 'bg-[#c5a059] text-black font-semibold shadow-sm'
                    : 'text-neutral-300 hover:text-white hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Search & Partner filter dropdown */}
          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="w-3.5 h-3.5 text-neutral-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              <input
                type="text"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Search materials, silk, coats..."
                className="bg-white/5 border border-white/10 rounded pl-8 pr-3 py-1.5 text-xs text-white placeholder-neutral-500 focus:outline-none focus:border-[#c5a059] w-48 sm:w-56"
              />
            </div>

            <select
              value={selectedPartnerFilter}
              onChange={e => setSelectedPartnerFilter(e.target.value)}
              className="bg-neutral-900 border border-white/10 rounded px-3 py-1.5 text-xs text-white focus:outline-none focus:border-[#c5a059]"
            >
              <option value="All">All Partner Houses</option>
              {partners.map(p => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Section Notice */}
        <div className="mt-4 flex items-center justify-between text-xs text-neutral-400">
          <span>
            Showing <strong className="text-white font-mono">{filteredProducts.length}</strong> masterworks across partner houses
          </span>
          <span className="text-neutral-500 italic">
            Clicking any product redirects you directly to that partner’s dedicated bespoke webpage
          </span>
        </div>
      </section>

      {/* Main Products Grid */}
      <section className="max-w-7xl mx-auto px-6 pb-20">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredProducts.map(product => {
            const partner = partners.find(p => p.id === product.partnerId);

            return (
              <div
                key={product.id}
                className="group flex flex-col justify-between bg-neutral-950/60 border border-white/10 hover:border-[#c5a059]/50 rounded-sm overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-xl"
              >
                {/* Product Image Area - clicking redirects to partner page */}
                <div
                  onClick={() => navigateTo('partner', product.partnerId, product.id)}
                  className="relative aspect-[4/3] bg-neutral-900 overflow-hidden cursor-pointer"
                >
                  <img
                    src={product.image}
                    alt={product.title}
                    referrerPolicy="no-referrer"
                    className="w-full h-full object-cover object-center group-hover:scale-104 transition-transform duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-80 group-hover:opacity-60 transition-opacity" />

                  {/* Partner House Tag Overlay */}
                  <div className="absolute top-3 left-3 bg-black/75 backdrop-blur-sm border border-white/10 px-2.5 py-1 text-[11px] text-[#c5a059] uppercase tracking-wider font-medium">
                    {product.partnerName}
                  </div>

                  {/* Category Pill replacement: quiet clean text */}
                  <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between text-xs text-white">
                    <span className="text-white/80 font-light">{product.category}</span>
                    <span className="text-[11px] text-[#c5a059] opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1 font-medium">
                      Visit Partner Page <ArrowRight className="w-3 h-3" />
                    </span>
                  </div>
                </div>

                {/* Content Area */}
                <div className="p-5 flex-1 flex flex-col justify-between space-y-4">
                  <div>
                    <div className="flex items-center justify-between gap-2 text-xs text-neutral-400 mb-1">
                      <span>{partner?.location || 'Paris Atelier'}</span>
                      <span className="font-mono text-[11px] text-neutral-400">Lead time: {product.leadTime.split(' ')[0]}</span>
                    </div>

                    <h3
                      onClick={() => navigateTo('partner', product.partnerId, product.id)}
                      className="font-editorial text-xl text-white font-medium hover:text-[#c5a059] transition-colors cursor-pointer line-clamp-1"
                    >
                      {product.title}
                    </h3>

                    <p className="text-xs text-neutral-300 line-clamp-2 mt-2 leading-relaxed font-light">
                      {product.description}
                    </p>

                    {/* Materials list */}
                    <div className="mt-3 flex flex-wrap gap-1 text-[11px] text-neutral-400">
                      {product.materials.map((mat, i) => (
                        <span key={i} className="after:content-['·'] after:ml-1 last:after:content-none text-neutral-400">
                          {mat}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Price and Primary Actions */}
                  <div className="pt-4 border-t border-white/10 flex items-center justify-between gap-3">
                    <div>
                      <span className="text-[10px] uppercase tracking-wider text-neutral-400 block">Atelier Bespoke</span>
                      <span className="text-lg font-mono font-medium text-white tracking-tight">
                        {product.currency === 'EUR' ? '€' : '$'}{product.price.toLocaleString()}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      {/* Chat with this Partner */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          openChatForPartner(product.partnerId, product.id);
                        }}
                        title={`Chat directly with ${product.partnerName} about this piece`}
                        className="p-2 rounded bg-white/5 hover:bg-white/15 text-neutral-300 hover:text-white border border-white/10 transition-colors"
                      >
                        <MessageSquare className="w-4 h-4 text-[#c5a059]" />
                      </button>

                      {/* Redirect to Partner Page CTA */}
                      <button
                        onClick={() => navigateTo('partner', product.partnerId, product.id)}
                        className="px-3.5 py-2 text-xs font-semibold tracking-wider uppercase text-black bg-[#c5a059] hover:bg-[#d4b069] rounded transition-all whitespace-nowrap flex items-center gap-1.5"
                      >
                        <span>View in Boutique</span>
                        <ArrowRight className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {filteredProducts.length === 0 && (
          <div className="text-center py-20 border border-dashed border-white/10 rounded p-8">
            <p className="text-neutral-400 font-editorial text-xl">No couture pieces match this criterion.</p>
            <button
              onClick={() => { setSelectedCategory('All'); setSelectedPartnerFilter('All'); setSearchQuery(''); }}
              className="mt-4 px-4 py-2 text-xs bg-white/10 hover:bg-white/20 text-white rounded font-medium"
            >
              Reset All Filters
            </button>
          </div>
        )}
      </section>
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Partner, Product } from '../types';
import {
  MessageSquare,
  ShieldCheck,
  Lock,
  ArrowLeft,
  ShoppingBag,
  Sparkles,
  Scissors,
  Check,
  ExternalLink,
  ShieldAlert,
  Send,
  Eye,
  FolderLock
} from 'lucide-react';

export const PartnerWebpage: React.FC = () => {
  const {
    currentUser,
    partners,
    products,
    selectedPartnerId,
    selectedProductId,
    navigateTo,
    openChatForPartner,
    setCheckoutProduct,
    setIsCheckoutModalOpen,
    chatThreads,
    sendChatMessage,
    canAccessCommunication,
    canAccessPartnerFiles
  } = useApp();

  const partner = partners.find(p => p.id === selectedPartnerId) || partners[0];
  const partnerProducts = products.filter(p => p.partnerId === partner.id);
  const activeProduct = partnerProducts.find(p => p.id === selectedProductId) || partnerProducts[0];

  const [selectedSize, setSelectedSize] = useState<string>(activeProduct?.sizes[0] || 'Standard Bespoke');
  const [inlineMessage, setInlineMessage] = useState<string>('');

  // Find active chat thread between current user and this partner
  const currentThread = chatThreads.find(
    t => t.partnerId === partner.id && t.clientId === currentUser.id
  );

  const isOwnerPartner = currentUser.role === 'partner' && currentUser.partnerId === partner.id;
  const isOtherPartner = currentUser.role === 'partner' && currentUser.partnerId !== partner.id;
  const isAdmin = currentUser.role === 'admin';

  const handleSendInlineChat = (e: React.FormEvent) => {
    e.preventDefault();
